public class Main {static <N extends Number> double average(N[] values){if(values.length==0)throw new IllegalArgumentException("Array cannot be empty");double sum=0;for(N n:values)sum+=n.doubleValue();return sum/values.length;}public static void main(String[] args){Integer[] i={10,20,30,40};Double[] d={10.5,20.5,30.5};Long[] l={100L,200L,300L};System.out.println("Integer average: "+average(i));System.out.println("Double average: "+average(d));System.out.println("Long average: "+average(l));}}
